document.getElementById('profile-photo').addEventListener('change',function(e){const file=e.target.files[0];if(file){const reader=new FileReader();reader.onload=function(event){document.getElementById('profile-preview').src=event.target.result;};reader.readAsDataURL(file);}});const usernameInput=document.getElementById('username');const usernameHint=document.getElementById('username-hint');usernameInput.addEventListener('input',function(){const isValid=/^[a-zA-Z0-9@.+_-]+$/.test(this.value);if(this.value.length>0&&!isValid){usernameHint.classList.add('error');usernameHint.textContent='Solo se permiten letras, dígitos y @/./+/-/_';}else{usernameHint.classList.remove('error');usernameHint.textContent='';}});document.getElementById('profile-form').addEventListener('submit',function(e){const username=usernameInput.value;const isValid=/^[a-zA-Z0-9@.+_-]+$/.test(username);if(!isValid){e.preventDefault();usernameHint.classList.add('error');usernameHint.textContent='Caracteres no válidos en el nombre de usuario';usernameInput.focus();}});document.getElementById('cancel-btn').addEventListener('click',function(){if(confirm('¿Estás seguro de que deseas cancelar los cambios?')){console.log('Cambios cancelados');}});;